<?php
require __DIR__.'/_common.php'; api_method_get();$slug=trim((string)($_GET['slug']??''));$lang=(string)($_GET['lang']??'id');
if(!api_slug($slug))api_out(['error'=>['code'=>'invalid_slug','message'=>'Provide a valid slug parameter.']],400);
if(!in_array($lang,['id','en','es','fr','ja'],true))api_out(['error'=>['code'=>'invalid_language','message'=>'Supported languages: id, en, es, fr, ja.']],400);
try{
 if($lang==='id'){$q=$pdo->prepare("SELECT p.id,p.title,p.slug,p.excerpt,p.seo_title,p.seo_description,p.content,p.cover_image,p.published_at,p.updated_at,u.name author FROM posts p LEFT JOIN users u ON u.id=p.author_id WHERE p.slug=? AND p.status='published' AND (p.published_at IS NULL OR p.published_at<=NOW()) LIMIT 1");$q->execute([$slug]);$post=$q->fetch();}
 else{$pdo->exec("CREATE TABLE IF NOT EXISTS post_translations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, post_id INT UNSIGNED NOT NULL, language_code VARCHAR(5) NOT NULL, title VARCHAR(220) NOT NULL, slug VARCHAR(240) NOT NULL, excerpt TEXT NULL, seo_title VARCHAR(220) NULL, seo_description VARCHAR(320) NULL, content LONGTEXT NOT NULL, status ENUM('draft','published') NOT NULL DEFAULT 'draft', updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_post_translation(post_id,language_code), UNIQUE KEY uq_translation_slug(language_code,slug), INDEX idx_translation_language_status(language_code,status), CONSTRAINT fk_translation_post FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$q=$pdo->prepare("SELECT p.id,t.title,t.slug,t.excerpt,t.seo_title,t.seo_description,t.content,p.cover_image,p.published_at,t.updated_at,u.name author,t.language_code FROM post_translations t JOIN posts p ON p.id=t.post_id LEFT JOIN users u ON u.id=p.author_id WHERE t.language_code=? AND t.slug=? AND t.status='published' AND p.status='published' AND (p.published_at IS NULL OR p.published_at<=NOW()) LIMIT 1");$q->execute([$lang,$slug]);$post=$q->fetch();}
 if(!$post)api_out(['error'=>['code'=>'not_found','message'=>'Published article not found.']],404);api_out(['data'=>$post]);
}catch(Throwable $e){error_log('NOWRD API post failed: '.$e->getMessage());api_out(['error'=>['code'=>'server_error','message'=>'Unable to retrieve article.']],500);}
